sh -c 'pkill -f "odin3-xbox/kee[p]"; pkill -x xboxd; for i in $(seq 20); do pidof xboxd > /dev/null || break; sleep 0.5; done'
sh -c 'D=/data/adb/odin3-xbox; mkdir -p $D && cp /data/local/tmp/odin3-xbox/xboxd $D/xboxd.new && mv -f $D/xboxd.new $D/xboxd'
sh -c 'D=/data/adb/odin3-xbox; cp /data/local/tmp/odin3-xbox/keep.sh $D/keep.new && mv -f $D/keep.new $D/keep.sh'
sh -c 'D=/data/adb/odin3-xbox; chown -R root:root $D && chmod 700 $D $D/xboxd $D/keep.sh'
sh -c 'cp /data/media/0/Android/data/com.miHoYo.Yuanshen.relWithDebInfo/files/xbox_dongle/xone_dongle_*.bin /data/adb/odin3-xbox/'
sh -c 'echo "$(date "+%m-%d %T") I Installed xboxd $(md5sum /data/adb/odin3-xbox/xboxd | cut -c1-8)" >> /data/local/tmp/odin3-xboxd.log'
sh -c 'setsid /data/adb/odin3-xbox/keep.sh < /dev/null > /dev/null 2>&1 & sleep 1'
